/**
 * Type chart for fire/water/grass (+ normal as neutral filler).
 * Keyed as [attacking type][defending type] -> damage multiplier.
 * Missing entries default to 1.0 (neutral).
 *
 * Rules: 2.0 = super effective, 0.5 = not very effective, 1.0 = neutral.
 */
export const TYPE_CHART: Record<PokemonType, Partial<Record<PokemonType, number>>> = {
  fire: {
    grass: 2.0, // fire burns grass
    water: 0.5, // water douses fire
    fire: 0.5,
  },
  water: {
    fire: 2.0, // water douses fire
    grass: 0.5, // grass absorbs water
    water: 0.5,
  },
  grass: {
    water: 2.0, // grass absorbs water
    fire: 0.5, // fire burns grass
    grass: 0.5,
  },
  normal: {}, // neutral against everything
};

export function typeMultiplier(attackType: PokemonType, defendType: PokemonType): number {
  return TYPE_CHART[attackType][defendType] ?? 1.0;
}
