import type { Move, PokemonType } from './types';

export interface DamageInput {
  level: number;
  power: number;
  atk: number;
  def: number;
}

export interface DamageModifiers {
  /** Same-type attack bonus; applied as x1.5 with floor after multiply. */
  stab?: boolean;
  /** Defending type (defaults to neutral 1.0). */
  defenderType?: PokemonType;
  moveType?: PokemonType;
}

/** STAB multiplier constant. */
export const STAB_MULTIPLIER = 1.5;

/**
 * Core damage formula:
 *   base = floor(floor(floor(2*Level/5 + 2) * Power * Atk / Def) / 50) + 2
 * then apply STAB x1.5 (floor after multiply),
 * then apply type chart multiplier (floor after multiply).
 */
export function calcDamage(input: DamageInput, mods: DamageModifiers = {}): number {
  const { level, power, atk, def } = input;

  const levelTerm = Math.floor((2 * level) / 5 + 2);
  const raw = Math.floor(levelTerm * power * atk) / def;
  let damage = Math.floor(Math.floor(raw) / 50) + 2;

  if (mods.stab) {
    damage = Math.floor(damage * STAB_MULTIPLIER);
  }

  if (mods.moveType && mods.defenderType) {
    damage = Math.floor(damage * typeMultiplier(mods.moveType, mods.defenderType));
  }

  return damage;
}

/** Convenience wrapper taking a Move + attacker/defender types directly. */
export function calcMoveDamage(
  input: DamageInput,
  move: Move,
  attackerType: PokemonType,
  defenderType: PokemonType
): number {
  return calcDamage(input, {
    stab: move.type === attackerType,
    moveType: move.type,
    defenderType,
  });
}
"})
