import { SeededCoin, type CoinSide } from './rng';
import type { BattleMon, Move } from './types';

export interface TurnEvent {
  turn: number;
  actor: string;
  move: string;
  target: string;
  damage: number;
  /** Target HP after this action. */
  targetHpAfter: number;
  fainted: boolean;
}

export interface BattleOptions {
  seed?: number;
}

/**
 * Resolves one action order for a turn.
 * Higher Speed acts first. On a Speed tie, an explicit seeded coin decides:
 * heads -> first combatant goes first, tails -> second combatant goes first.
 */
export function resolveOrder(
  a: BattleMon,
  b: BattleMon,
  coin: SeededCoin
): [BattleMon, BattleMon] {
  if (a.stats.spe > b.stats.spe) return [a, b];
  if (b.stats.spe > a.stats.spe) return [b, a];
  const side: CoinSide = coin.flip();
  return side === 'heads' ? [a, b] : [b, a];
}

function executeAction(
  attacker: BattleMon,
  defender: BattleMon,
  move: Move,
  turn: number
): TurnEvent {
  const damage = calcMoveDamage(
    { level: attacker.stats.level, power: move.power, atk: attacker.stats.atk, def: defender.stats.def },
    move,
    attacker.type,
    defender.type
  );
  defender.hp = Math.max(0, defender.hp - damage);
  return {
    turn,
    actor: attacker.name,
    move: move.name,
    target: defender.name,
    damage,
    targetHpAfter: defender.hp,
    fainted: defender.hp === 0,
  };
}

export interface ScriptedBattleResult {
  events: TurnEvent[];
  winner: string | null;
}

/**
 * Runs a scripted battle: each mon plays its moves in the given script order,
 * one move per turn. Faster mon acts first (ties via seeded coin). If a mon
 * faints mid-turn, the remaining action is skipped and the battle ends.
 */
export function runScriptedBattle(
  first: BattleMon,
  second: BattleMon,
  scriptFirst: Move[],
  scriptSecond: Move[],
  options: BattleOptions = {}
): ScriptedBattleResult {
  const coin = new SeededCoin(options.seed ?? 1);
  const events: TurnEvent[] = [];
  let winner: string | null = null;

  const maxTurns = Math.max(scriptFirst.length, scriptSecond.length);

  for (let turn = 1; turn <= maxTurns; turn++) {
    const [faster, slower] = resolveOrder(first, second, coin);
    const fasterIsFirst = faster === first;

    const fasterMove = (fasterIsFirst ? scriptFirst : scriptSecond)[turn - 1];
    const slowerMove = (fasterIsFirst ? scriptSecond : scriptFirst)[turn - 1];

    const event1 = executeAction(faster, slower, fasterMove, turn);
    events.push(event1);
    if (event1.fainted) {
      winner = faster.name;
      break;
    }

    if (!slowerMove) continue;
    const event2 = executeAction(slower, faster, slowerMove, turn);
    events.push(event2);
    if (event2.fainted) {
      winner = slower.name;
      break;
    }
  }

  if (winner === null) {
    // Battle ran out of script: higher remaining HP wins; exact tie -> null.
    if (first.hp > second.hp) winner = first.name;
    else if (second.hp > first.hp) winner = second.name;
  }

  return { events, winner };
}
"})
