/**
 * Explicit seeded coin: deterministic PRNG (mulberry32) driving fair flips.
 * Same seed => identical flip sequence, every time.
 */
export class SeededCoin {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  /** One deterministic coin flip. */
  flip(): CoinSide {
    // mulberry32 step
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const rand = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    return rand < 0.5 ? 'heads' : 'tails';
  }
}
