import { calcDamage } from '../src/damage';
import { typeMultiplier } from '../src/typechart';

describe('type chart', () => {
  it('fire is strong vs grass, weak vs water', () => {
    expect(typeMultiplier('fire', 'grass')).toBe(2.0);
    expect(typeMultiplier('fire', 'water')).toBe(0.5);
  });

  it('water is strong vs fire, weak vs grass', () => {
    expect(typeMultiplier('water', 'fire')).toBe(2.0);
    expect(typeMultiplier('water', 'grass')).toBe(0.5);
  });

  it('grass is strong vs water, weak vs fire', () => {
    expect(typeMultiplier('grass', 'water')).toBe(2.0);
    expect(typeMultiplier('grass', 'fire')).toBe(0.5);
  });

  it('same-type and normal matchups are neutral', () => {
    expect(typeMultiplier('fire', 'fire')).toBe(1.0);
    expect(typeMultiplier('water', 'water')).toBe(1.0);
    expect(typeMultiplier('grass', 'grass')).toBe(1.0);
    expect(typeMultiplier('normal', 'fire')).toBe(1.0);
    expect(typeMultiplier('normal', 'grass')).toBe(1.0);
  });
});

describe('damage formula vectors', () => {
  const base = { level: 50, power: 80, atk: 100, def: 100 };

  it('Level 50 / Power 80 / Atk 100 / Def 100 -> base 37', () => {
    expect(calcDamage(base)).toBe(37);
  });

  it('same vector with STAB -> 55', () => {
    expect(calcDamage(base, { stab: true })).toBe(55);
  });

  it('STAB plus super-effective -> 110', () => {
    expect(calcDamage(base, { stab: true, moveType: 'fire', defenderType: 'grass' })).toBe(110);
  });

  it('STAB plus not-very-effective -> 27 (floor(55 * 0.5))', () => {
    expect(calcDamage(base, { stab: true, moveType: 'fire', defenderType: 'water' })).toBe(27);
  });

  it('no STAB but super-effective -> 74', () => {
    expect(calcDamage(base, { moveType: 'grass', defenderType: 'water' })).toBe(74);
  });
});
"})
