result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/battle.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { runScriptedBattle, resolveOrder } from '../src/battle';
import { SeededCoin } from '../src/rng';
import type { BattleMon, Move } from '../src/types';

function mon(name: string, type: BattleMon['type'], spe: number, maxHp: number): BattleMon {
  return {
    name,
    type,
    stats: { level: 50, atk: 100, def: 100, spe, maxHp },
    hp: maxHp,
  };
}

const EMBER: Move = { name: 'Ember', type: 'fire', power: 80 };
const FLAMETHROWER: Move = { name: 'Flamethrower', type: 'fire', power: 90 };
const VINE_WHIP: Move = { name: 'Vine Whip', type: 'grass', power: 45 };
const FIRE_BLAST: Move = { name: 'Fire Blast', type: 'fire', power: 110 };
const WATER_GUN: Move = { name: 'Water Gun', type: 'water', power: 80 };
const BUBBLE: Move = { name: 'Bubble', type: 'water', power: 60 };
const AQUA_TAIL: Move = { name: 'Aqua Tail', type: 'water', power: 90 };
const TACKLE: Move = { name: 'Tackle', type: 'normal', power: 40 };

describe('turn resolution', () => {
  it('higher Speed acts first', () => {
    const fast = mon('Fastmon', 'fire', 120, 200);
    const slow = mon('Slowmon', 'water', 60, 200);
    const [first] = resolveOrder(fast, slow, new SeededCoin(42));
    expect(first.name).toBe('Fastmon');
  });

  it('Speed ties are broken by an explicit seeded coin, reproducibly', () => {
    const a = mon('Alpha', 'fire', 90, 200);
    const b = mon('Beta', 'water', 90, 200);

    // Same seed => identical order sequence.
    const coin1 = new SeededCoin(7);
    const coin2 = new SeededCoin(7);
    const seq1 = Array.from({ length: 8 }, () => resolveOrder(a, b, coin1)[0].name);
    const seq2 = Array.from({ length: 8 }, () => resolveOrder(a, b, coin2)[0].name);
    expect(seq1).toEqual(seq2);

    // The tie-break genuinely uses both coin sides over enough flips.
    const coin3 = new SeededCoin(7);
    const sides = new Set(Array.from({ length: 16 }, () => coin3.flip()));
    expect(sides.has('heads')).toBe(true);
    expect(sides.has('tails')).toBe(true);
  });
});

describe('scripted 2-mon battle', () => {
  // Blazeap (fire) outspeeds Aquatle (water): no ties needed here.
  const blazeap = () => mon('Blazeap', 'fire', 90, 200);
  const aquatle = () => mon('Aquatle', 'water', 70, 180);

  const blazeapScript: Move[] = [
    EMBER, // T1
    FLAMETHROWER, // T2
    VINE_WHIP, // T3
    FIRE_BLAST, // T4
    FIRE_BLAST, // T5
    FIRE_BLAST, // T6 -> KO
  ];
  const aquatleScript: Move[] = [
    WATER_GUN, // T1
    BUBBLE, // T2
    AQUA_TAIL, // T3
    TACKLE, // T4
    TACKLE, // T5
  ];

  it('resolves the full fight with an exact turn-by-turn HP log', () => {
    const { events, winner } = runScriptedBattle(
      blazeap(),
      aquatle(),
      blazeapScript,
      aquatleScript,
      { seed: 1337 }
    );

    expect(events.map((e) => e.targetHpAfter)).toEqual([
      153, 173, // Turn 1: Ember 27dmg -> 153; Water Gun 27dmg -> 173
      123, 152, // Turn 2: Flamethrower 30dmg -> 123; Bubble 21dmg -> 152
      81, 122, // Turn 3: Vine Whip 42dmg (super-effective) -> 81; Aqua Tail 30dmg -> 122
      44, 103, // Turn 4: Fire Blast 37dmg -> 44; Tackle 19dmg -> 103
      7, 84, //   Turn 5: Fire Blast 37dmg -> 7; Tackle 19dmg -> 84
      0, //      Turn 6: Fire Blast 37dmg -> KO, Aquatle never acts
    ]);

    expect(winner).toBe('Blazeap');

    // Full event-by-event assertion (actor, move, damage dealt, remaining HP).
    expect(events).toMatchObject([
      { turn: 1, actor: 'Blazeap', move: 'Ember', target: 'Aquatle', damage: 27, targetHpAfter: 153, fainted: false },
      { turn: 1, actor: 'Aquatle', move: 'Water Gun', target: 'Blazeap', damage: 27, targetHpAfter: 173, fainted: false },
      { turn: 2, actor: 'Blazeap', move: 'Flamethrower', target: 'Aquatle', damage: 30, targetHpAfter: 123, fainted: false },
      { turn: 2, actor: 'Aquatle', move: 'Bubble', target: 'Blazeap', damage: 21, targetHpAfter: 152, fainted: false },
      { turn: 3, actor: 'Blazeap', move: 'Vine Whip', target: 'Aquatle', damage: 42, targetHpAfter: 81, fainted: false },
      { turn: 3, actor: 'Aquatle', move: 'Aqua Tail', target: 'Blazeap', damage: 30, targetHpAfter: 122, fainted: false },
      { turn: 4, actor: 'Blazeap', move: 'Fire Blast', target: 'Aquatle', damage: 37, targetHpAfter: 44, fainted: false },
      { turn: 4, actor: 'Aquatle', move: 'Tackle', target: 'Blazeap', damage: 19, targetHpAfter: 103, fainted: false },
      { turn: 5, actor: 'Blazeap', move: 'Fire Blast', target: 'Aquatle', damage: 37, targetHpAfter: 7, fainted: false },
      { turn: 5, actor: 'Aquatle', move: 'Tackle', target: 'Blazeap', damage: 19, targetHpAfter: 84, fainted: false },
      { turn: 6, actor: 'Blazeap', move: 'Fire Blast', target: 'Aquatle', damage: 37, targetHpAfter: 0, fainted: true },
    ]);
  });

  it('is fully deterministic for a given seed', () => {
    const run = () =>
      runScriptedBattle(blazeap(), aquatle(), blazeapScript, aquatleScript, { seed: 99 }).events.map(
        (e) => [e.actor, e.targetHpAfter]
      );
    expect(run()).toEqual(run());
  });

  it('skips the second action when the faster mon KOs mid-turn', () => {
    // One-shot: super-effective grass hit on a fragile water mon.
    const attacker = mon('Leafy', 'grass', 150, 999);
    attacker.stats.atk = 500;
    const victim = mon('Squishy', 'water', 10, 20);
    const { events, winner } = runScriptedBattle(attacker, victim, [VINE_WHIP], [TACKLE], {
      seed: 5,
    });

    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({ turn: 1, actor: 'Leafy', fainted: true, targetHpAfter: 0 });
    expect(winner).toBe('Leafy');
    expect(victim.hp).toBe(0);
  });
});
"})
